pi_op('Builder V1 V2 admissions pinning stable URL retire and mixed export',function()use(&$versioned,&$a,&$b){$v1=pi_release(pi_simple('versions'));$a=pi_frame($v1,'a@example.test');$cap=pf_mint($a);$v2=pi_api('clone',array('id'=>$v1['id'],'revision'=>$v1['revision']));$q=pi_question($v2,'answer');$v2=pi_edit($v2,$q['id'],static function($n){$c=json_decode($n['content']['snapshot'],true);$c['label']='V2 question';$n['content']['snapshot']=Canonical::json($c);$n['content']['sha256']=hash('sha256',$n['content']['snapshot']);return $n;});$v2=pi_release($v2);$b=pi_frame($v2,'b@example.test');pe_assert($a['version_id']===$v1['id']&&$b['version_id']===$v2['id'],'Pinning');pe_assert($v1['public_url']===$v2['public_url'],'URL changed');$before=(new P\StudyVersionRepository(pf_db()))->find($v1['id']);$v1=pi_api('retire',array('id'=>$v1['id'],'revision'=>$v1['revision']));pe_assert($before['protocol_hash']===(new P\StudyVersionRepository(pf_db()))->find($v1['id'])['protocol_hash'],'Retire hash');$a=pi_finish(pf_runtime()->redeem(pi_p($v1)['public'],$cap));$b=pi_finish($b);$out=(new G\ExportAdapter(pf_db()))->dataset($v1['study_id']);pe_assert(count($out['manifest'])===2,'Combined manifest');foreach(array($a,$b) as $f)foreach(pf_intents($f['access']['execution_id']) as $intent)pe_assert((new P\StudyExecutionRepository(pf_db()))->find($intent['execution_id'])['study_version_id']===$f['version_id'],'Intent wrong version');$versioned=$v2;});
pi_op('OPEN PAUSED OPEN CLOSED operational state admission delivery existing science unchanged',function(){ $e=pi_release(pi_simple('states'));$f=pi_frame($e);$hash=(new P\StudyVersionRepository(pf_db()))->find($e['id'])['protocol_hash'];foreach(array('PAUSED','OPEN','CLOSED') as $state){$e=pi_api('activate',array('id'=>$e['id'],'revision'=>$e['revision'],'state'=>$state));$entry=pf_enroll(pi_p($e));pe_assert(($state==='OPEN')===!isset($entry['entry']),'Admission '.$state);pe_assert(!isset(pi_reload($f)['entry']),'Existing session blocked '.$state);pe_assert($hash===(new P\StudyVersionRepository(pf_db()))->find($e['id'])['protocol_hash'],'Schedule mutated');if($state==='PAUSED'){$intent=pf_intents($f['access']['execution_id'],'ASSESSMENT_AVAILABLE')[0];pe_assert(pf_delivery($intent)['success'],'Existing participant delivery paused');}}});
pi_op('two devices partial refresh stale CAS duplicate submit reload final',function(){ $e=pi_release(pi_simple('devices'));$a=pi_frame($e);$stale=pe_request($a,'partial',pi_answers($a));$a=pi_act($a,'partial',pi_answers($a));$b=pf_runtime()->redeem(pi_p($e)['public'],pf_mint($a));pe_equal($a['view']['snapshot']['responses'],$b['view']['snapshot']['responses'],'Device partial');$stale['csrf']=$b['csrf'];$stale['command_id']='STALE_'.bin2hex(random_bytes(6));pe_reject(function()use($e,$b,$stale){pf_runtime()->handle(pi_p($e)['public'],$b['token'],$stale);},'REVISION_CONFLICT');$req=pe_request($b,'submit',pi_answers($b));$one=pf_runtime()->handle(pi_p($e)['public'],$b['token'],$req);$two=pf_runtime()->handle(pi_p($e)['public'],$b['token'],$req);pe_assert($one['view']['next_action']['kind']==='FINISHED'&&$two['view']['next_action']['kind']==='FINISHED'&&pf_participant($b)['verification_state']==='VERIFIED','Link-verified device incorrectly demands another email review');pe_equal($one['view']['snapshot'],$two['view']['snapshot'],'Duplicate submit changed saved response');pe_assert(count((new P\SubmissionJournalRepository(pf_db()))->list($a['access']['execution_id']))===1,'Duplicate Storage');pi_finish($one);pe_assert(pi_reload($a)['view']['next_action']['kind']==='FINISHED','Device A stale');});
pi_op('corrupt published protocol fails closed runtime without rewrite',function(){ $e=pi_release(pi_simple('corruptprotocol'));$f=pi_frame($e);$row=(new P\StudyVersionRepository(pf_db()))->find($e['id']);$bad=$row['protocol_json'].' ';pf_db()->query(pf_db()->prepare('UPDATE '.pf_db()->table('study_versions').' SET protocol_hash=%s WHERE id=%s',str_repeat('0',64),$e['id']));try{try{pi_reload($f);throw new RuntimeException('Corrupt protocol accepted');}catch(P\IntegrityFailure $expected){}pe_assert((new P\StudyVersionRepository(pf_db()))->find($e['id'])['protocol_hash']===str_repeat('0',64),'Silent repair');}finally{pf_db()->query(pf_db()->prepare('UPDATE '.pf_db()->table('study_versions').' SET protocol_hash=%s WHERE id=%s',$row['protocol_hash'],$e['id']));}});
pi_op('checkpoint corruption operational error no overwrite',function(){ $e=pi_release(pi_simple('checkpoint'));$f=pi_frame($e);$id=$f['access']['execution_id'];$row=(new P\StudyExecutionRepository(pf_db()))->find($id);pf_db()->query(pf_db()->prepare('UPDATE '.pf_db()->table('study_executions').' SET checkpoint_hash=%s WHERE id=%s',str_repeat('0',64),$id));try{pe_assert(pf_owner()->view($id)['next_action']['kind']==='OPERATIONAL_ERROR','Checkpoint accepted');pe_assert((new P\StudyExecutionRepository(pf_db()))->find($id)['checkpoint_json']===$row['checkpoint_json'],'Overwrite');}finally{pf_db()->query(pf_db()->prepare('UPDATE '.pf_db()->table('study_executions').' SET checkpoint_hash=%s WHERE id=%s',$row['checkpoint_hash'],$id));}});
