pi_op('B2 salt rotation blocks enrollment until original salt restored',function(){ $e=pi_release(pi_simple('salt'));$f=pi_frame($e,'blocked@example.test');$shell=pf_runtime()->redeem(pi_p($e)['public'],pf_mint($f,'WITHDRAWAL_OPTIONS'));pf_runtime()->handle(pi_p($e)['public'],$shell['token'],array('action'=>'withdraw','command_id'=>'SALT_B2','csrf'=>$shell['csrf'],'mode'=>'DO_NOT_USE','confirm_privacy'=>'1','expected_revision'=>$shell['view']['revision']));EIPSI_Privacy_Data_Cleanup_Service::run_study_engine(pf_db(),$f['access']['execution_id']);$filter=static function($salt,$scheme){return $scheme==='auth'?str_repeat('ROTATED_TEST_ONLY',8):$salt;};add_filter('salt',$filter,10,2);try{pe_reject(function()use($e){pf_enroll(pi_p($e),'new@example.test');},'PRIVACY_EMAIL_KEY_RECONCILIATION_REQUIRED');}finally{remove_filter('salt',$filter,10);}pe_assert(isset(pf_enroll(pi_p($e),'blocked@example.test')['entry']),'B2 re-enrolled');});
