pi_op('100 participants export bounded queries and B2 volume',function()use(&$metrics){global $wpdb;$GLOBALS['pf_now']='2026-10-12T11:00:00Z';$e=pi_release(pi_simple('volume'));$frames=array();$start=microtime(true);for($i=0;$i<100;$i++)$frames[]=pi_finish(pi_frame($e,'volume'.$i.'@example.test'));$q=$wpdb->num_queries;$m=memory_get_peak_usage(true);$data=(new G\ExportAdapter(pf_db()))->dataset($e['study_id']);$queries=$wpdb->num_queries-$q;pe_assert(count($data['rows'])===100&&$queries<20,'Export volume N+1 '.$queries);$f=$frames[0];$shell=pf_runtime()->redeem(pi_p($e)['public'],pf_mint($f,'WITHDRAWAL_OPTIONS'));pf_runtime()->handle(pi_p($e)['public'],$shell['token'],array('action'=>'withdraw','command_id'=>'VOLUME_B2','csrf'=>$shell['csrf'],'mode'=>'DO_NOT_USE','confirm_privacy'=>'1','expected_revision'=>$shell['view']['revision']));$out=EIPSI_Privacy_Data_Cleanup_Service::run_study_engine(pf_db(),$f['access']['execution_id']);pe_assert(in_array($out['cleanup_state'],array('COMPLETE_LOCAL','PARTIAL'),true),'Volume cleanup');pe_assert(count((new G\ExportAdapter(pf_db()))->dataset($e['study_id'])['rows'])===99,'B2 volume export');$metrics=array('participants'=>100,'export_rows'=>100,'export_queries'=>$queries,'seconds_enroll_complete_export'=>round(microtime(true)-$start,3),'peak_memory_bytes'=>$m,'cleanup'=>$out['cleanup_state']);});
